package com.aistock.prediction.explanation;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;
@org.junit.jupiter.api.extension.ExtendWith(org.springframework.boot.test.system.OutputCaptureExtension.class)
class PortfolioMaasClientTest {
 final ObjectMapper m=new ObjectMapper();final Map<String,String> f=Map.of("AS_OF","2026-10-16","COVERAGE_LIMIT","完整同日","FRESHNESS_LIMIT","无法确认","DATE_LIMIT","逐行日期","BASIS_LIMIT","仅参考");
 @Test void dedicatedCallStrictlyRejectsInnerAndOuterCorruptionWithoutRetry()throws Exception{for(String mode:List.of("ok","inner-duplicate","inner-trailing","outer-duplicate","outer-trailing","oversized","auth","rate","malformed")){var captured=new AtomicReference<JsonNode>();var calls=new AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/chat",e->{calls.incrementAndGet();captured.set(m.readTree(e.getRequestBody()));String content=mode.equals("inner-duplicate")?"{\"paragraphs\":[],\"paragraphs\":[]}":mode.equals("inner-trailing")?"{} {}":"{\"status\":\"OUT_OF_SCOPE\",\"topic\":\"LIMITATION\",\"paragraphs\":[]}";var env=m.createObjectNode();env.putArray("choices").addObject().putObject("message").put("content",content);String raw=mode.equals("outer-duplicate")?"{\"choices\":[],\"choices\":[]}":mode.equals("oversized")?"x".repeat(131073):mode.equals("malformed")?"not-json":m.writeValueAsString(env)+(mode.equals("outer-trailing")?" {}":"");byte[] b=raw.getBytes(java.nio.charset.StandardCharsets.UTF_8);e.sendResponseHeaders(mode.equals("auth")?403:mode.equals("rate")?429:200,b.length);try{e.getResponseBody().write(b);}finally{e.close();}});server.start();try{var client=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","m","private",true,m,Duration.ofSeconds(2),true);if(mode.equals("ok")){assertEquals("OUT_OF_SCOPE",client.generatePortfolioQuestion("IGNORE_PRIVATE_RULES",f).path("status").asText());var messages=captured.get().path("messages");assertFalse(messages.get(0).path("content").asText().contains("IGNORE_PRIVATE_RULES"));var user=m.readTree(messages.get(1).path("content").asText());assertEquals("IGNORE_PRIVATE_RULES",user.path("question").asText());assertEquals(m.valueToTree(f),user.path("facts"));}else{var error=assertThrows(BusinessException.class,()->client.generatePortfolioQuestion("解释",f));assertFalse(error.getMessage().contains("private"));if(mode.equals("oversized"))assertEquals("AI_UNAVAILABLE",error.code());if(mode.startsWith("inner")||mode.startsWith("outer")||mode.equals("malformed"))assertEquals("AI_OUTPUT_INVALID",error.code());}assertEquals(1,calls.get());}finally{server.stop(0);}}}
 @Test void deadlineIncludesResponseBodyAndCancelsWithoutRetry(org.springframework.boot.test.system.CapturedOutput output)throws Exception{var calls=new AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var executor=java.util.concurrent.Executors.newSingleThreadExecutor();server.setExecutor(executor);server.createContext("/chat",e->{calls.incrementAndGet();e.getRequestBody().readAllBytes();e.sendResponseHeaders(200,0);try{for(int i=0;i<20;i++){e.getResponseBody().write(' ');e.getResponseBody().flush();Thread.sleep(100);}}catch(Exception ignored){}finally{e.close();}});server.start();try{var client=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","m","private",true,m,Duration.ofMillis(250),true);long started=System.nanoTime();assertEquals("AI_TIMEOUT",assertThrows(BusinessException.class,()->client.generatePortfolioQuestion("风险",f)).code());assertTrue(output.getAll().contains("category=TIMEOUT"));assertFalse(output.getAll().contains("private"));assertTrue(Duration.ofNanos(System.nanoTime()-started).toMillis()<1500);assertEquals(1,calls.get());}finally{server.stop(0);executor.shutdownNow();}}

 @Test void documentedV4PortfolioProfileDisablesThinkingAndLeavesOtherRequestsUnchanged()throws Exception {
  var captured=new AtomicReference<JsonNode>();var calls=new AtomicInteger();
  var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/chat",e->{calls.incrementAndGet();captured.set(m.readTree(e.getRequestBody()));var envelope=m.createObjectNode();envelope.putArray("choices").addObject().putObject("message").put("content","{}");byte[] b=m.writeValueAsBytes(envelope);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});server.start();
  try {
   var client=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","deepseek-v4-flash","private",true,m,Duration.ofSeconds(2),true);
   client.generatePortfolioQuestion("解释",f);
   assertEquals("disabled",captured.get().path("thinking").path("type").asText());
   assertEquals(1200,captured.get().path("max_tokens").asInt());assertFalse(captured.get().path("stream").asBoolean(true));
   client.generate(f);assertFalse(captured.get().has("thinking"));
   var other=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","unknown-model","private",true,m,Duration.ofSeconds(2),true);
   other.generatePortfolioQuestion("解释",f);assertFalse(captured.get().has("thinking"));assertEquals(3,calls.get());
  }finally{server.stop(0);}
 }
 @Test void portfolioConnectionFailureHasSafeCategoryWithoutSecretOrQuestion(org.springframework.boot.test.system.CapturedOutput output)throws Exception {
  int port;try(var socket=new java.net.ServerSocket(0)){port=socket.getLocalPort();}
  var client=new HttpMaasClient("http://127.0.0.1:"+port+"/chat","deepseek-v4-flash","private-diagnostic-key",true,m,Duration.ofSeconds(2),true);
  assertEquals("AI_CONNECTION_FAILED",assertThrows(BusinessException.class,()->client.generatePortfolioQuestion("PRIVATE_QUESTION",f)).code());
  assertTrue(output.getAll().contains("category=CONNECTION"));assertFalse(output.getAll().contains("private-diagnostic-key"));assertFalse(output.getAll().contains("PRIVATE_QUESTION"));
 }
}
